ALTER TABLE public.user_settings ADD COLUMN week_starts_on text NOT NULL DEFAULT 'monday' CHECK (week_starts_on IN ('sunday','monday')), ADD COLUMN monitoring_enabled boolean NOT NULL DEFAULT true, ADD COLUMN proactive_notifications boolean NOT NULL DEFAULT true;
ALTER TABLE public.farmer_goals DROP CONSTRAINT farmer_goals_metric_check;
ALTER TABLE public.farmer_goals ADD CONSTRAINT farmer_goals_metric_check CHECK (metric IN ('margin','cost_per_kg','custom','expected_profit'));
CREATE TABLE public.farm_monitor_state (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, dirty boolean NOT NULL DEFAULT true, last_checked_at timestamptz, last_error text);
GRANT ALL ON public.farm_monitor_state TO service_role;
ALTER TABLE public.farm_monitor_state ENABLE ROW LEVEL SECURITY;
INSERT INTO public.farm_monitor_state(user_id) SELECT id FROM public.profiles ON CONFLICT DO NOTHING;
CREATE TABLE public.farm_monitor_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, event_key text NOT NULL, fingerprint text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_key,fingerprint));
GRANT ALL ON public.farm_monitor_events TO service_role;
ALTER TABLE public.farm_monitor_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.farm_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, currency text NOT NULL CHECK(currency IN ('USD','INR','CNY','GBP','JPY')), time_zone text NOT NULL, week_starts_on text NOT NULL CHECK(week_starts_on IN ('sunday','monday')), snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,period_start,period_end,currency));
GRANT SELECT ON public.farm_reports TO authenticated;
GRANT ALL ON public.farm_reports TO service_role;
ALTER TABLE public.farm_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_owner_read ON public.farm_reports FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX farm_monitor_due ON public.farm_monitor_state(last_checked_at NULLS FIRST);
CREATE INDEX farm_reports_owner_date ON public.farm_reports(user_id,period_start DESC);
CREATE FUNCTION public.queue_farm_monitor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.farm_monitor_state(user_id,dirty) VALUES(CASE WHEN TG_OP='DELETE' THEN OLD.farmer_id ELSE NEW.farmer_id END,true) ON CONFLICT(user_id) DO UPDATE SET dirty=true; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.queue_farm_monitor() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER queue_harvest_analysis AFTER INSERT OR UPDATE OR DELETE ON public.harvests FOR EACH ROW EXECUTE FUNCTION public.queue_farm_monitor();
CREATE FUNCTION public.queue_new_farm_monitor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.farm_monitor_state(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.queue_new_farm_monitor() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER queue_new_farm AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.queue_new_farm_monitor();
CREATE FUNCTION public.deliver_farm_alert(p_user_id uuid,p_key text,p_fingerprint text,p_details jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE event_id uuid; BEGIN INSERT INTO public.farm_monitor_events(user_id,event_key,fingerprint) VALUES(p_user_id,p_key,p_fingerprint) ON CONFLICT DO NOTHING RETURNING id INTO event_id; IF event_id IS NULL THEN RETURN false; END IF; INSERT INTO public.notifications(user_id,title,body,event_type,details) VALUES(p_user_id,'Farm observation','Evidence-backed farm observation','farm_alert',p_details); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.deliver_farm_alert(uuid,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.deliver_farm_alert(uuid,text,text,jsonb) TO service_role;
CREATE FUNCTION public.deliver_farm_report(p_user_id uuid,p_start date,p_end date,p_currency text,p_zone text,p_week text,p_snapshot jsonb,p_notify boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE report_id uuid; BEGIN INSERT INTO public.farm_reports(user_id,period_start,period_end,currency,time_zone,week_starts_on,snapshot) VALUES(p_user_id,p_start,p_end,p_currency,p_zone,p_week,p_snapshot) ON CONFLICT DO NOTHING RETURNING id INTO report_id; IF report_id IS NULL THEN RETURN false; END IF; IF p_notify THEN INSERT INTO public.notifications(user_id,title,body,event_type,details) VALUES(p_user_id,'Weekly farm report','Weekly farm report','farm_report',jsonb_build_object('reportId',report_id,'start',p_start,'end',p_end,'currency',p_currency,'timeZone',p_zone,'snapshot',p_snapshot)); END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.deliver_farm_report(uuid,date,date,text,text,text,jsonb,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.deliver_farm_report(uuid,date,date,text,text,text,jsonb,boolean) TO service_role;